Method.Source:
/// <summary>
/// Form AVAInventSiteDelegateDialog
/// </summary>
[Form]
public class AVAInventSiteDelegateDialog extends FormRun
{
    SalesTable salesTable;
    QueryBuildRange inventSiteDelegate_agentSite;

}

/// <summary>
/// init method
/// </summary>
public void init()
{
    super();

    if(this.args().dataset() == tableNum(SalesTable))
    {
        salesTable = this.args().record();
    }
    else
    {
        throw Error(strFmt("@NDX:NXAErrorWrongRecordType", this.args().record().dataSource().name(), tableId2Name(tableNum(SalesTable))));
    }

}

public void closeOk()
{
    super();

    try
    {
        this.updateSalesTable();
        this.updateSalesLines();
        this.previewDelegationReport();
    }
    catch
    {
        throw;
    }
}

/// <summary>
///     AVA <c>updateSalesTable</c> method.
/// </summary>
public void updateSalesTable()
{
    salesTable.selectForUpdate(true);

    ttsbegin;
    if (salesTable.isInterCompanyOrder())
    {
        salesTable.AVADelegatedToAgentIC = NoYes::Yes;
    }
    else
    {
        salesTable.AVADelegatedToAgent      = NoYes::Yes;
    }
    salesTable.InventSiteId             = inventSiteDelegate.SiteId;
    salesTable.InventLocationId         = InventSiteDelegate.SiteId;        // intentionally using SiteId for LocationId - based on requirement
    salesTable.AVADelegationUserId      = curUserId();
    salesTable.AVADelegationDateTime    = DateTimeUtil::getSystemDateTime();
    salesTable.AVADlvResponsible        = HcmWorker::userId2Worker(curUserId());
    salesTable.doUpdate();
    ttscommit;
}

/// <summary>
/// loops related SalesLines
/// </summary>
public void updateSalesLines()
{
    SalesLine locSalesLine;

    ttsbegin;

    while select forupdate locSalesLine
        where locSalesLine.SalesId == salesTable.SalesId
    {
        this.updateSalesLineInventDim(locSalesLine);
    }

    ttscommit;
}

/// <summary>
/// Updates salesLine inventDim
/// </summary>
/// <param name = "_salesLine">SalesLine</param>
public void updateSalesLineInventDim(SalesLine _salesLine)
{
    InventDim locInventDim;
    SalesLine locSalesLine = _salesLine;

    locInventDim = locSalesLine.inventDim();

    locInventDim.InventLocationId   = salesTable.InventLocationId;
    locInventDim.InventSiteId       = salesTable.InventSiteId;

    locInventDim = InventDim::findOrCreate(locInventDim);

    locSalesLine.InventDimId = locInventDim.inventDimId;
    locSalesLine.doUpdate();
}

/// <summary>
///     AVA <c>previewDelegationReport</c> method.
/// </summary>
public void previewDelegationReport()
{
    MenuFunction    locMenuFunction;
    if(salesTable.RecId)
    {
        // open with dialog
        locMenuFunction = new MenuFunction(menuitemActionStr(AVASalesOrderDelegationReportAction), MenuItemType::Action);
        //locMenuFunction = new MenuFunction(menuitemActionStr(AVASalesOrderDelegationReportActionPreview), MenuItemType::Action);
        locMenuFunction.run(this.args());
    }
}

/// <summary>
/// init method of InventSiteDelegate FormDataSource
/// </summary>
public void init()
{
    QueryBuildDataSource inventSiteDelegate_qbds;

    super();

    inventSiteDelegate_qbds         = InventSiteDelegate_q.dataSourceTable(tableNum(InventSite));
    inventSiteDelegate_qbds.clearDynalinks();

    inventSiteDelegate_agentSite    = inventSiteDelegate_qbds.addRange(fieldNum(InventSite, AVAAgentSite));
    inventSiteDelegate_agentSite.status(RangeStatus::Hidden);
}

/// <summary>
/// executeQuery method of InventSiteDelegate FormDataSource
/// </summary>
public void executeQuery()
{
    InventSiteDelegate_agentSite.value(queryValue(NoYes::Yes));

    super();
}
